INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 26, 'theory', 'Quiz: closures and decorators');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 26, 0, 'What is a closure?', '["A function with no arguments", "A nested function that remembered the variables of the outer one", "A function that closes a file", "A class with a __call__ method"]', 1, 'A closure takes its environment along: the outer function''s variables live on inside the inner function that was returned.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 26, 1, 'Why do you need the word nonlocal inside a nested function?', '["To make a variable global", "To assign to a variable of the outer function", "To forbid changes", "It is the same as return"]', 1, 'Without nonlocal, an assignment would create a new local variable.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 26, 2, 'What does the line @timer above def square(x): ... mean?', '["Call timer after square", "square = timer(square)", "Copy timer into square", "Nothing special"]', 1, 'The @ sign is shorthand: the function''s name gets the result of calling the decorator.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 26, 3, 'What happens if a decorator''s wrapper calls func(*args, **kwargs) but doesn''t return the result?', '["Everything works", "The decorated function will return None", "Python raises an error at definition time", "The result is doubled"]', 1, 'Without return the original''s result is lost: the call returns None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 26, 4, 'What does @wraps(func) do above the inner wrapper?', '["Speeds the function up", "Copies the original function''s name and docstring onto the wrapper", "Forbids calling it", "Adds a cache"]', 1, 'wraps keeps __name__ and __doc__, so debugging and help see the real function.');
